<?php
session_start();if(($_SESSION['role']??'')!=='admin'){header('Location: /authenication/login/login.php');exit;}
require_once(__DIR__.'/../../Database/db/db.php');$pdo=get_db();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="techworld-admin-export-'.date('Ymd-His').'.csv"');header('X-Content-Type-Options: nosniff');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Type','ID','Name or title','Email or category','Role or instructor']);$safe=function($value){$value=(string)($value??'');return preg_match('/^[=+@\-]/',$value)?"'".$value:$value;};$q=$pdo->query('SELECT id,full_name,username,email,role,status FROM users ORDER BY id');while($r=$q->fetch(PDO::FETCH_ASSOC)){fputcsv($out,['User',$r['id'],$safe($r['full_name']?:$r['username']),$safe($r['email']),$r['role'].' / '.$r['status']]);}$q=$pdo->query('SELECT c.id,c.title,c.category,c.instructor_id,u.username FROM courses c LEFT JOIN users u ON u.id=c.instructor_id ORDER BY c.id');while($r=$q->fetch(PDO::FETCH_ASSOC)){fputcsv($out,['Course',$r['id'],$safe($r['title']),$safe($r['category']),$safe($r['username']??'Unassigned')]);}fclose($out);exit;
